##! experimental.givens

// REGION is named so the notebook surfaces a control for it, which is what
// `to=self` needs somewhere to put the clicked value.
import "orders.malloy"
import { REGION } from "givens.malloy"

##! experimental.givens
## autorun=false

// An explicit title, which beats both the doc comment below it and the "Orders
// since" heading above — the same precedence a dashboard's `title=` has.
## title="Orders in a window"
##" Order counts from a date the reader picks.

// A notebook surfaces the givens it imports, exactly as a dashboard file does,
// so the Parameters panel shows these and nothing else.
import { orders } from "orders.malloy"
import { BRAND, MIN_AMOUNT, SINCE } from "givens.malloy"

##! experimental.givens
// Written as a DATE LITERAL, matching the declaration's own default
// (`given: SINCE :: date is @2024-01-01`), which is the natural spelling and
// the one that used to publish a full ISO timestamp the query endpoint 400s on.
## givens { SINCE=@2024-03-01 }

import { orders } from "orders.malloy"
import { SINCE } from "givens.malloy"

