import {
   order_items,
   products,
   regions,
   brand_suggest
} from "storefront.malloy"

# description="Narrow to one product category. Leave empty for all"
# label="Category" control=select suggest { source=products dimension=category }
given: CATEGORY :: filter<string> is f''

# description="One or more brands. Leave empty for all"
# label="Brand" control=multiselect suggest { query=brand_suggest dimension=brand }
given: BRAND :: filter<string> is f''

# description="Narrow to one US sales region. Leave empty for all"
# label="Region" control=select suggest { source=regions dimension=region }
given: REGION :: filter<string> is f''

#(doc) The overview notebook's tiles, each over the order lines its controls select
source: overview_tiles is order_items extend {
  # label="Key figures"
  # big_value
  view: kpis is key_figures + { where: category ~ $CATEGORY, where: brand ~ $BRAND, where: region ~ $REGION, where: created_at >= $SINCE, where: sale_price ~ $MIN_SALE }

  # label="Revenue by month"
  view: revenue_trend is sales_by_month + { where: category ~ $CATEGORY, where: brand ~ $BRAND, where: region ~ $REGION, where: created_at >= $SINCE, where: sale_price ~ $MIN_SALE }

  # label="Revenue by state"
  view: revenue_by_state is sales_by_state + { where: category ~ $CATEGORY, where: brand ~ $BRAND, where: region ~ $REGION, where: created_at >= $SINCE, where: sale_price ~ $MIN_SALE }

  # label="Revenue by category"
  view: revenue_by_category is by_category + { where: category ~ $CATEGORY, where: brand ~ $BRAND, where: region ~ $REGION, where: created_at >= $SINCE, where: sale_price ~ $MIN_SALE }

  # label="Top products"
  view: best_sellers is top_products + { where: category ~ $CATEGORY, where: brand ~ $BRAND, where: region ~ $REGION, where: created_at >= $SINCE, where: sale_price ~ $MIN_SALE }
}
